enum EVENT
{
    EVT_SURFER_LAND,
    EVT_SURFER_WIPEOUT,
    EVT_SURFER_DUCK_DIVE,
    EVT_TRICK_REGION_CHANGE,
    EVT_TRICK_FACE_BEGIN,
    EVT_TRICK_FACE_END,
    EVT_SCORING_SERIES_END,
    EVT_SCORING_CHAIN_END
};

class SpecialMeter
{
    char event_recipient[4];
    int playerIdx;
    float fillage;
    bool isEnabled;
    float specialTime;
    int trickRegion;
    bool isDoingTrick;
    int faceLink;
    float faceLinkTimer;
    float current_special_time;
    int numPerfects;

public:
    void OnEvent(const EVENT event, const int param1, const int param2);
};

void SpecialMeter::OnEvent(const EVENT event, const int param1, const int param2)
{
    if (param1 != playerIdx)
        return;

    if (event == EVT_TRICK_FACE_BEGIN)
    {
        switch (faceLink)
        {
        case 0 : faceLinkTimer = 1.0f; break;
        case 1 : faceLinkTimer = 0.75f; break;
        case 2 : faceLinkTimer = 0.50f; break;
        case 3 : faceLinkTimer = 0.25f; break;
        case 4 : faceLinkTimer = 0.10f; break;
        case 5 : faceLinkTimer = 0.05f; break;
        default : faceLinkTimer = 0.01f; break;
        }

        faceLink++;
    }
    else if (event == EVT_TRICK_FACE_END)
    {

    }
    else if (event == EVT_SURFER_LAND)
    {
        if (param2 & 0x01)
            numPerfects++;
        else
            numPerfects = 0;
    }
    else if (event == EVT_SCORING_CHAIN_END)
    {
        numPerfects = 0;
    }
}
